using UnityEditor;
using UnityEngine;

namespace Parasite.EditorTools
{
    /// <summary>
    /// Import settings for everything under Resources/Audio (generated by Tools/audio/*.sh):
    /// gameplay music stems compressed in memory (sample-locked looping), long cues streamed, ambience beds compressed
    /// in memory, dialogue/vocals compressed in memory, short SFX decompressed on load. Clips are authored mono/stereo and
    /// loudness-normalised offline, so Force To Mono (which also peak-normalises) stays off.
    /// Bump <see cref="GetVersion"/> after changing a rule to reimport the affected clips.
    /// </summary>
    public class AudioImportRules : AssetPostprocessor
    {
        const string Root = "Assets/Parasite/Resources/Audio/";
        static readonly string[] Stems = { "mus_city_calm", "mus_lab_calm", "mus_tension", "mus_chase" };

        public override uint GetVersion() => 5;

        static bool Has(string[] names, string file)
        {
            foreach (var n in names) if (file.StartsWith(n)) return true;
            return false;
        }

        void OnPreprocessAudio()
        {
            if (!assetPath.StartsWith(Root)) return;
            var importer = (AudioImporter)assetImporter;
            string sub = assetPath.Substring(Root.Length);
            string file = System.IO.Path.GetFileNameWithoutExtension(assetPath);
            var s = importer.defaultSampleSettings;
            s.compressionFormat = AudioCompressionFormat.Vorbis;
            s.sampleRateSetting = AudioSampleRateSetting.PreserveSampleRate;
            s.preloadAudioData = true;
            importer.loadInBackground = false;
            if (sub.StartsWith("Music/"))
            {
                bool stem = Has(Stems, file) || file.StartsWith("stinger");
                s.loadType = stem ? AudioClipLoadType.CompressedInMemory : AudioClipLoadType.Streaming;
                s.quality = 0.55f;
                s.preloadAudioData = stem;
                importer.forceToMono = false;
            }
            else if (sub.StartsWith("Ambience/"))
            {
                s.loadType = AudioClipLoadType.CompressedInMemory;
                s.quality = 0.45f;
                importer.forceToMono = false;   // positional loops are authored mono; beds stay stereo
            }
            else if (sub.StartsWith("Voice/") || sub.StartsWith("Vocals/"))
            {
                s.loadType = AudioClipLoadType.CompressedInMemory;
                s.quality = 0.45f;
                s.preloadAudioData = sub.StartsWith("Vocals/");
                importer.forceToMono = false;   // authored mono (Unity's Force To Mono would also peak-normalise)
            }
            else
            {
                // Sfx/ and the original Kenney clips at the root: short one-shots
                s.loadType = AudioClipLoadType.DecompressOnLoad;
                s.quality = 0.6f;
                importer.forceToMono = false;   // one-shots are authored mono except thunder/ending_sting (2D)
            }
            importer.defaultSampleSettings = s;
        }
    }
}
